#define main embedded_navigation_main
#include "../../main.mm"
#undef main

namespace {
struct Snapshot {
    std::array<float,184> observation{};
    std::array<float,320> depth{};
    std::array<float,85> memory_clearance{};
    RLPhysicsState state{};
};

static Snapshot capture(Metal& metal, WWorld world, uint32_t seed) {
    SimConfig config;
    config.n=1; config.mode=17; config.eval=1; config.family=14;
    config.speed=1.5f; config.max_steps=400; config.seed=seed;
    config.geometry_memory=1; config.velocity_contract=1;
    Sim sim(metal,config,1);
    *static_cast<WWorld*>(sim.worlds.contents)=world;
    auto cb=[metal.queue commandBuffer];
    auto c=sim.configs[0];
    metal.dispatch(cb,sim.depth_p,320,{sim.states,sim.runs,sim.worlds,sim.sensors,sim.physics,c,sim.poses});
    metal.dispatch(cb,sim.memory_points_p,640,{sim.states,sim.runs,sim.sensors,sim.poses,sim.memory_points,sim.physics,c});
    metal.dispatch(cb,sim.memory_candidates_p,85,{sim.states,sim.worlds,sim.memory_points,sim.memory_clearances,c});
    metal.dispatch(cb,sim.observe_p,1,{sim.states,sim.runs,sim.worlds,sim.sensors,sim.obs,sim.co,sim.physics,c,sim.poses,sim.memory_clearances},64);
    metal.finish(cb);
    Snapshot result;
    std::memcpy(result.observation.data(),sim.obs.contents,sizeof(result.observation));
    std::memcpy(result.depth.data(),sim.sensors.contents,sizeof(result.depth));
    std::memcpy(result.memory_clearance.data(),sim.memory_clearances.contents,sizeof(result.memory_clearance));
    std::memcpy(&result.state,sim.states.contents,sizeof(result.state));
    return result;
}

static double max_difference(const float* a,const float* b,size_t count,size_t* index=nullptr) {
    double best=0;
    for(size_t i=0;i<count;i++) {
        const double d=std::fabs(double(a[i])-double(b[i]));
        if(d>best){best=d;if(index)*index=i;}
    }
    return best;
}
}

int main() {@autoreleasepool { try {
    const std::string bank=std::string(SOURCE_DIR)+"/results/challenge-bank-mirrored-v1.jsonl";
    std::string bank_hash;
    const auto levels=challenge_evaluation::load_split(bank,"train",challenge_evaluation::sha256_file(std::string(SOURCE_DIR)+"/world.hpp"),bank_hash);
    Metal metal;
    metal.compile(base_source()+PPO_TRAINER_MSL);
    std::ofstream out(std::string(SOURCE_DIR)+"/results/imitation-review/mirror-reset.csv");
    require(bool(out),"cannot open mirror-reset.csv");
    out<<"failure_id,obstacles,sensor_depth_horizontal_mirror_l1_m,actor_depth_features_max_abs_delta,actor_context_max_abs_delta,actor_context_index,geometry_hint_max_abs_delta,clearance_max_abs_delta_m,goal_same,start_position_error_m,identity_quaternion_error\n";
    uint count=0; double max_depth=0,max_context=0,max_hint=0,max_clearance=0;
    for(const auto& level:levels) {
        if(level.family!=14 || level.failure_id.find("-mirror-y")!=std::string::npos)continue;
        WWorld left=level.world,right=level.world;
        left.goal[1]=right.goal[1]=0.0f;
        for(uint i=0;i<left.count;i++) {
            right.obstacles[i].center[1]=-left.obstacles[i].center[1];
            right.obstacles[i].velocity[1]=-left.obstacles[i].velocity[1];
        }
        auto a=capture(metal,left,level.seed),b=capture(metal,right,level.seed);
        size_t context_index=0;
        const double depth_diff=max_difference(a.observation.data(),b.observation.data(),160);
        const double context_diff=max_difference(a.observation.data()+160,b.observation.data()+160,21,&context_index);
        const double hint_diff=max_difference(a.observation.data()+181,b.observation.data()+181,3);
        const double clearance_diff=max_difference(a.memory_clearance.data(),b.memory_clearance.data(),85);
        double row_l1=0;
        for(size_t y=0;y<16;y++)for(size_t x=0;x<20;x++)
            row_l1+=std::fabs(double(a.depth[y*20+x])-b.depth[y*20+(19-x)]);
        double start_error=0,identity_error=0;
        const float expected_position[3]={0,0,1.5f},identity[4]={1,0,0,0};
        for(uint j=0;j<3;j++)start_error=std::max(start_error,std::fabs(double(a.state.position[j]-expected_position[j])));
        for(uint j=0;j<4;j++)identity_error=std::max(identity_error,std::fabs(double(a.state.orientation_wxyz[j]-identity[j])));
        out<<level.failure_id<<','<<left.count<<','<<std::setprecision(9)<<row_l1<<','<<depth_diff<<','<<context_diff<<','<<(context_index+160)<<','<<hint_diff<<','<<clearance_diff<<",1,"<<start_error<<','<<identity_error<<'\n';out.flush();
        max_depth=std::max(max_depth,depth_diff);max_context=std::max(max_context,context_diff);max_hint=std::max(max_hint,hint_diff);max_clearance=std::max(max_clearance,clearance_diff);count++;
    }
    std::cout<<"mirror_reset_pairs="<<count<<" bank_sha256="<<bank_hash<<" max_depth_feature_delta="<<max_depth<<" max_context_delta="<<max_context<<" max_hint_delta="<<max_hint<<" max_memory_clearance_delta="<<max_clearance<<" output=results/imitation-review/mirror-reset.csv\n";
    return 0;
} catch(const std::exception& error) { std::cerr<<error.what()<<'\n';return 1; }}}
